package com.cgsplits;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Data;

/**
 * One Gauntlet attempt. Serialized to JSON as-is, so keep fields simple.
 * All times are in game ticks (1 tick = 600ms), counted from entering the instance.
 */
@Data
public class Run
{
	public enum Mode
	{
		UNKNOWN,
		NORMAL,
		CORRUPTED
	}

	public enum EndReason
	{
		COMPLETED,
		DIED,
		/** Left the instance (teleported out, logged out, disconnected). */
		LEFT,
		/** Plugin was turned off mid-run. */
		ABANDONED
	}

	private long startedAt;
	private Mode mode = Mode.UNKNOWN;
	private boolean completed;
	private EndReason endReason;
	/** Armour held when entering the Hunllef room; null if the run never got there. */
	private Armour armourAtEnter;
	private int ticks;
	private Map<Milestone, Integer> splits = new LinkedHashMap<>();

	/** Times the game prints in chat on completion, e.g. "6:42.60". Ground truth for validation. */
	private String officialDuration;
	private String officialPrep;

	/**
	 * How many ticks our live timer was off from the game's official times before being
	 * corrected (positive = we were ahead). Kept to check the timer stays in sync.
	 */
	private Integer prepDriftTicks;
	private Integer timerDriftTicks;

	public boolean hasSplit(Milestone milestone)
	{
		return splits.containsKey(milestone);
	}

	/**
	 * The milestone's display time in ticks: since the run started for most milestones, or the
	 * length of the segment for ones timed from another split (the Hunllef fight, each HP
	 * quarter). Null if a split it needs is missing.
	 */
	public Integer splitTime(Milestone milestone)
	{
		Integer end = splits.get(milestone.end());
		if (end == null || milestone.since() == null)
		{
			return end;
		}
		Integer start = splits.get(milestone.since());
		return start == null ? null : end - start;
	}

	/**
	 * Runs saved by older versions have a split per demi-boss (and may contain null keys
	 * for milestones that no longer exist). Fold all three demis into one DEMIS split,
	 * reached when the last of them died, and drop the old keys.
	 */
	public void migrateLegacySplits()
	{
		splits.remove(null);
		Integer bear = splits.remove(Milestone.BEAR);
		Integer dragon = splits.remove(Milestone.DRAGON);
		Integer darkBeast = splits.remove(Milestone.DARK_BEAST);
		// The Demi split is the first demi killed
		Integer firstDemi = null;
		for (Integer demi : new Integer[]{bear, dragon, darkBeast})
		{
			if (demi != null && (firstDemi == null || demi < firstDemi))
			{
				firstDemi = demi;
			}
		}
		if (firstDemi != null && !splits.containsKey(Milestone.DEMIS))
		{
			splits.put(Milestone.DEMIS, firstDemi);
		}

		// Partial armour enters are burger enters now
		if (armourAtEnter == Armour.PARTIAL)
		{
			armourAtEnter = Armour.BURGER;
		}

		// Older versions kept the sentence's full stop ("5:42.60.") and didn't snap to the
		// game's official times; fix both now
		if (officialPrep != null && officialPrep.endsWith("."))
		{
			officialPrep = officialPrep.substring(0, officialPrep.length() - 1);
		}
		if (officialDuration != null && officialDuration.endsWith("."))
		{
			officialDuration = officialDuration.substring(0, officialDuration.length() - 1);
		}
		Integer officialPrepTicks = TimeFormat.parseOfficial(officialPrep);
		if (officialPrepTicks != null && splits.containsKey(Milestone.BOSS_ROOM))
		{
			splits.put(Milestone.BOSS_ROOM, officialPrepTicks);
		}
		Integer officialTicks = TimeFormat.parseOfficial(officialDuration);
		if (officialTicks != null && completed)
		{
			ticks = officialTicks;
			splits.put(Milestone.HUNLLEF, officialTicks);
		}
	}

	/** End reason, with a fallback for runs saved before it was recorded. */
	public EndReason resolveEndReason()
	{
		if (endReason != null)
		{
			return endReason;
		}
		return completed ? EndReason.COMPLETED : EndReason.LEFT;
	}

	/** The latest milestone this run reached, or null if it reached none. */
	public Milestone furthestSplit()
	{
		Milestone furthest = null;
		int furthestTick = -1;
		for (Map.Entry<Milestone, Integer> split : splits.entrySet())
		{
			if (split.getValue() >= furthestTick)
			{
				furthest = split.getKey();
				furthestTick = split.getValue();
			}
		}
		return furthest;
	}

	/**
	 * Walked into the Hunllef room without ever holding a corrupted weapon (e.g. testing or
	 * throwing a run). These aren't real enters, so they're not saved or counted.
	 */
	public boolean isWeaponlessEnter()
	{
		return hasSplit(Milestone.BOSS_ROOM) && !hasSplit(Milestone.FIRST_WEAPON);
	}

	/** A run that ended (died or left) before reaching the Hunllef room. */
	public boolean isReset()
	{
		EndReason reason = resolveEndReason();
		return !hasSplit(Milestone.BOSS_ROOM) && (reason == EndReason.DIED || reason == EndReason.LEFT);
	}

	/** Runs whose mode wasn't detected are assumed to be corrupted; normal runs are only saved when tracked. */
	public boolean isCorrupted()
	{
		return mode != Mode.NORMAL;
	}
}

package com.cgsplits;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import lombok.Getter;

/**
 * Aggregate stats across runs, including incomplete ones, like paceman.gg's stats page:
 * how many runs reached each split, and the average and best time to get there.
 */
@Getter
public class RunStats
{
	@Getter
	public static class MilestoneStats
	{
		private int count;
		private long totalTicks;
		private int bestTicks = Integer.MAX_VALUE;

		void add(int ticks)
		{
			count++;
			totalTicks += ticks;
			bestTicks = Math.min(bestTicks, ticks);
		}

		public int getAverageTicks()
		{
			return count == 0 ? 0 : (int) Math.round((double) totalTicks / count);
		}
	}

	private int runs;
	private int completions;
	private int deaths;
	private int resets;
	private final Map<Milestone, MilestoneStats> milestones = new EnumMap<>(Milestone.class);
	/** Enter times (prep) grouped by armour worn on entry. */
	private final Map<Armour, MilestoneStats> enters = new EnumMap<>(Armour.class);
	/** Completed runs grouped by armour worn on entry. */
	private final Map<Armour, Integer> completionsByArmour = new EnumMap<>(Armour.class);

	static RunStats of(Iterable<Run> runs)
	{
		RunStats stats = new RunStats();
		for (Run run : runs)
		{
			stats.runs++;
			switch (run.resolveEndReason())
			{
				case COMPLETED:
					stats.completions++;
					break;
				case DIED:
					stats.deaths++;
					break;
				default:
					break;
			}
			if (run.isReset())
			{
				stats.resets++;
			}
			for (Milestone milestone : Milestone.values())
			{
				Integer time = run.splitTime(milestone);
				if (time != null)
				{
					stats.milestones.computeIfAbsent(milestone, m -> new MilestoneStats()).add(time);
				}
			}

			Armour armour = run.getArmourAtEnter();
			Integer enter = run.getSplits().get(Milestone.BOSS_ROOM);
			if (armour != null && enter != null)
			{
				stats.enters.computeIfAbsent(armour, a -> new MilestoneStats()).add(enter);
				if (run.isCompleted())
				{
					stats.completionsByArmour.merge(armour, 1, Integer::sum);
				}
			}
		}
		return stats;
	}

	public Map<Milestone, MilestoneStats> getMilestones()
	{
		return Collections.unmodifiableMap(milestones);
	}

	public Map<Armour, MilestoneStats> getEnters()
	{
		return Collections.unmodifiableMap(enters);
	}

	/** Share of enters with this armour that ended in a kill, 0-100, or -1 with no enters. */
	public int completionPercent(Armour armour)
	{
		MilestoneStats e = enters.get(armour);
		if (e == null || e.getCount() == 0)
		{
			return -1;
		}
		return (int) Math.round(100.0 * completionsByArmour.getOrDefault(armour, 0) / e.getCount());
	}

	/** Share of all runs that reached this milestone, 0-100. */
	public int percentReached(Milestone milestone)
	{
		MilestoneStats m = milestones.get(milestone);
		return m == null || runs == 0 ? 0 : (int) Math.round(100.0 * m.getCount() / runs);
	}
}

package com.cgsplits;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Stores every run (completed or not) as its own JSON file in the plugin's data folder,
 * .runelite/plugin-data/cg-splits/runs/, and derives the PB, best splits and aggregate stats
 * from them. All file access goes through RuneLite's {@link Filepath}.
 */
@Slf4j
@Singleton
public class RunStore
{
	/** Where runs are saved; set by {@link #load(Filepath)} when the plugin starts. */
	private volatile Filepath runsDir;

	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	/** Corrupted runs only, newest first. Replaced wholesale, never mutated, so reads need no lock. */
	private volatile List<Run> runs = new ArrayList<>();
	private volatile Run personalBest;
	private volatile Map<Milestone, Integer> bestSplits = new EnumMap<>(Milestone.class);
	private volatile RunStats stats = RunStats.of(new ArrayList<>());

	@Inject
	RunStore(Gson gson, ScheduledExecutorService executor)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.executor = executor;
	}

	/** Called (on the thread that changed the data) whenever runs are loaded or saved. */
	public void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	public void removeListener(Runnable listener)
	{
		listeners.remove(listener);
	}

	/**
	 * Loads every saved run from the plugin's data folder.
	 *
	 * @param pluginDirectory the folder RuneLite gives this plugin (see {@code Plugin#getPluginDirectory})
	 */
	public synchronized void load(Filepath pluginDirectory)
	{
		runsDir = pluginDirectory.joinSegment("runs");

		List<Run> loaded = new ArrayList<>();
		if (runsDir.isDirectory())
		{
			List<Filepath> files;
			try (Stream<Filepath> walk = runsDir.walk(1))
			{
				files = walk
					.filter(f -> f.isFile() && f.getFileName().endsWith(".json"))
					.collect(Collectors.toList());
			}
			catch (IOException e)
			{
				log.warn("Couldn't list saved Gauntlet runs in {}", runsDir, e);
				files = Collections.emptyList();
			}

			for (Filepath file : files)
			{
				try (Reader reader = file.openBufferedReader())
				{
					Run run = gson.fromJson(reader, Run.class);
					// Runs saved before weaponless enters were ignored are skipped here too
					if (run != null && run.isCorrupted() && !run.isWeaponlessEnter())
					{
						run.migrateLegacySplits();
						loaded.add(run);
					}
				}
				catch (Exception e)
				{
					log.warn("Skipping unreadable run file {}", file, e);
				}
			}
		}
		update(loaded);
		log.debug("Loaded {} Gauntlet runs", loaded.size());
	}

	public synchronized void save(Run run)
	{
		executor.execute(() -> write(run));
		if (run.isCorrupted())
		{
			List<Run> updated = new ArrayList<>(runs);
			updated.add(run);
			update(updated);
		}
	}

	/** Corrupted runs, newest first. */
	public List<Run> getRuns()
	{
		return runs;
	}

	/**
	 * Fastest completed corrupted run other than {@code run}, or null. Used to colour a run's
	 * splits: a new PB is compared against the PB it beat, not against itself.
	 */
	public Run getPersonalBestExcluding(Run run)
	{
		Run best = null;
		for (Run other : runs)
		{
			if (other != run && other.isCompleted() && (best == null || other.getTicks() < best.getTicks()))
			{
				best = other;
			}
		}
		return best;
	}

	/** Best (lowest) tick a recorded split was ever reached at, counted from the run start. */
	public Integer bestTick(Milestone milestone)
	{
		Integer best = null;
		for (Run run : runs)
		{
			Integer tick = run.getSplits().get(milestone);
			if (tick != null && (best == null || tick < best))
			{
				best = tick;
			}
		}
		return best;
	}

	/** Fastest completed corrupted run, or null. */
	public Run getPersonalBest()
	{
		return personalBest;
	}

	/** Best-ever tick each milestone was reached at, across all corrupted runs. */
	public Map<Milestone, Integer> getBestSplits()
	{
		return bestSplits;
	}

	public RunStats getStats()
	{
		return stats;
	}

	private void update(List<Run> newRuns)
	{
		newRuns.sort(Comparator.comparingLong(Run::getStartedAt).reversed());

		Run pb = null;
		Map<Milestone, Integer> best = new EnumMap<>(Milestone.class);
		for (Run run : newRuns)
		{
			if (run.isCompleted() && (pb == null || run.getTicks() < pb.getTicks()))
			{
				pb = run;
			}
			for (Milestone milestone : Milestone.values())
			{
				Integer time = run.splitTime(milestone);
				if (time != null)
				{
					best.merge(milestone, time, Math::min);
				}
			}
		}

		runs = Collections.unmodifiableList(newRuns);
		personalBest = pb;
		bestSplits = best;
		stats = RunStats.of(newRuns);

		for (Runnable listener : listeners)
		{
			listener.run();
		}
	}

	private void write(Run run)
	{
		Filepath dir = runsDir;
		if (dir == null)
		{
			log.warn("Not saving Gauntlet run: data folder not set up");
			return;
		}
		Filepath file = dir.joinSegment(run.getStartedAt() + ".json");
		try
		{
			dir.createDirectories();
			try (Writer writer = file.openBufferedWriter())
			{
				gson.toJson(run, writer);
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to save Gauntlet run to {}", file, e);
		}
	}
}

package com.cgsplits;

import java.util.Collection;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;

/**
 * Run state machine and split detection. Deliberately has no RuneLite dependencies:
 * the plugin translates client events into these calls, which keeps this unit-testable.
 */
public class RunTracker
{
	public enum State
	{
		IDLE,
		PREP,
		BOSS,
		FINISHED
	}

	/** Ticks to wait after the Hunllef dies for the completion chat messages before saving. */
	static final int SAVE_DELAY_TICKS = 10;

	/**
	 * The game's own Gauntlet timer starts 4 ticks after the "entered Gauntlet" varbit flips.
	 * Measured against the official "Preparation time" message on real runs: starting on the
	 * flip put us 4 ticks ahead, and starting on arrival (1 tick later) put us 3 ticks ahead.
	 */
	static final int GAME_TIMER_START_DELAY = 4;

	private static final Pattern WEAPON = Pattern.compile("^(corrupted|crystal) (staff|bow|halberd) \\((basic|attuned|perfected)\\)$");
	private static final Pattern ARMOUR = Pattern.compile("^(corrupted|crystal) (helm|body|legs) \\((basic|attuned|perfected)\\)$");

	@Getter
	private State state = State.IDLE;
	@Getter
	private Run current;
	/** The most recently ended run, kept so the overlay can keep showing it. */
	@Getter
	private Run lastRun;

	private boolean primed;
	private boolean wasInGauntlet;
	private boolean diedThisRun;
	private boolean awaitingArrival;
	private int ticksSinceEntered;
	/** See {@link #GAME_TIMER_START_DELAY}. */
	private final int startDelayTicks;
	/** Ticks between the varbit flipping and arriving in the instance, for timer diagnostics. */
	@Getter
	private int arrivalDelayTicks;
	private int ticksSinceFinish;
	private final Set<String> perfectedTypes = new HashSet<>();
	/** 0 none, 1 basic, 2 attuned, 3 perfected. */
	private int bestWeaponTier;
	private final Set<String> armourSlots = new HashSet<>();

	/** Starts the timer the same tick the "entered Gauntlet" varbit flips (used by tests). */
	public RunTracker()
	{
		this(0);
	}

	/**
	 * @param startDelayTicks ticks after the "entered Gauntlet" varbit flips before the timer
	 *                        starts, to line up with the game's own timer
	 */
	public RunTracker(int startDelayTicks)
	{
		this.startDelayTicks = startDelayTicks;
	}

	public boolean isRunning()
	{
		return state == State.PREP || state == State.BOSS;
	}

	/**
	 * Called once per game tick.
	 *
	 * @param inGauntlet the "entered Gauntlet" varbit is set
	 * @param inInstance the player has actually arrived in the instanced maze. The varbit flips a
	 *                   few ticks before the teleport finishes, and the game's own timer only
	 *                   starts on arrival, so the run starts on the first tick both are true.
	 * @return a run that has ended and should be saved, or null
	 */
	public Run onTick(boolean inGauntlet, boolean inInstance, boolean inBossRoom, Run.Mode regionMode, long now)
	{
		// The first tick after (re)starting only records state, so loading the plugin
		// mid-run does not start a run with a wrong timer.
		if (!primed)
		{
			primed = true;
			wasInGauntlet = inGauntlet;
			return null;
		}

		boolean entered = inGauntlet && !wasInGauntlet;
		wasInGauntlet = inGauntlet;

		switch (state)
		{
			case IDLE:
				if (entered)
				{
					awaitingArrival = true;
					arrivalDelayTicks = 0;
					ticksSinceEntered = 0;
				}
				if (awaitingArrival)
				{
					if (!inGauntlet)
					{
						awaitingArrival = false;
					}
					else if (inInstance && ticksSinceEntered >= startDelayTicks)
					{
						awaitingArrival = false;
						start(now);
						applyMode(regionMode);
					}
					else
					{
						if (!inInstance)
						{
							arrivalDelayTicks++;
						}
						ticksSinceEntered++;
					}
				}
				return null;

			case PREP:
			case BOSS:
				if (!inGauntlet)
				{
					// Died or left before the Hunllef died
					return end(false);
				}
				current.setTicks(current.getTicks() + 1);
				applyMode(regionMode);
				if (state == State.PREP && inBossRoom)
				{
					current.setArmourAtEnter(Armour.classify(armourSlots.size(), bestWeaponTier));
					split(Milestone.BOSS_ROOM);
					state = State.BOSS;
				}
				return null;

			case FINISHED:
				ticksSinceFinish++;
				if (!inGauntlet || ticksSinceFinish >= SAVE_DELAY_TICKS)
				{
					return end(true);
				}
				return null;
		}
		return null;
	}

	public void onNpcDeath(String npcName)
	{
		if (!isRunning() || npcName == null)
		{
			return;
		}

		String name = npcName.toLowerCase(Locale.ROOT);
		applyMode(modeFromName(name));

		if (name.contains("hunllef"))
		{
			finish();
		}
		else if (name.endsWith("bear") || name.endsWith("dark beast") || name.endsWith("dragon"))
		{
			// Most routes only kill the one or two demis their weapons need, so split on the first
			split(Milestone.DEMIS);
		}
	}

	/** Called with the names of every item currently in the inventory and equipment. */
	public void onItems(Collection<String> itemNames)
	{
		if (!isRunning())
		{
			return;
		}

		for (String raw : itemNames)
		{
			String name = raw.toLowerCase(Locale.ROOT);

			Matcher weapon = WEAPON.matcher(name);
			if (weapon.matches())
			{
				applyMode(modeFromName(name));
				split(Milestone.FIRST_WEAPON);
				bestWeaponTier = Math.max(bestWeaponTier, weaponTier(weapon.group(3)));
				if ("perfected".equals(weapon.group(3)))
				{
					perfectedTypes.add(weapon.group(2));
				}
				continue;
			}

			Matcher armour = ARMOUR.matcher(name);
			if (armour.matches())
			{
				applyMode(modeFromName(name));
				armourSlots.add(armour.group(2));
			}
		}

		if (!perfectedTypes.isEmpty())
		{
			split(Milestone.FIRST_PERFECTED);
		}
		if (perfectedTypes.size() >= 2)
		{
			split(Milestone.SECOND_PERFECTED);
		}
		if (armourSlots.size() >= 3)
		{
			split(Milestone.FULL_ARMOUR);
		}
	}

	/** The game's own completion messages. Also acts as a fallback finish trigger. */
	public void onOfficialTimes(String duration, String prep)
	{
		Run run = state == State.FINISHED || isRunning() ? current : null;
		if (run == null)
		{
			return;
		}
		if (duration != null)
		{
			run.setOfficialDuration(duration);
			if (isRunning())
			{
				finish();
			}
			// The game's clock is the source of truth: snap the finish to it
			Integer ticks = TimeFormat.parseOfficial(duration);
			if (ticks != null)
			{
				run.setTimerDriftTicks(run.getSplits().getOrDefault(Milestone.HUNLLEF, run.getTicks()) - ticks);
				run.setTicks(ticks);
				run.getSplits().put(Milestone.HUNLLEF, ticks);
			}
		}
		if (prep != null)
		{
			run.setOfficialPrep(prep);
			Integer ticks = TimeFormat.parseOfficial(prep);
			if (ticks != null)
			{
				Integer ours = run.getSplits().get(Milestone.BOSS_ROOM);
				if (ours != null)
				{
					run.setPrepDriftTicks(ours - ticks);
					// Move the HP splits with the entry so their time since entering stays the same
					for (Milestone m : Milestone.values())
					{
						if (Milestone.HP_THRESHOLDS.contains(m))
						{
							run.getSplits().computeIfPresent(m, (k, v) -> v - (ours - ticks));
						}
					}
				}
				run.getSplits().put(Milestone.BOSS_ROOM, ticks);
			}
		}
	}

	/**
	 * The Hunllef's health bar, as a fraction from 0 to 1. Records the 75/50/25% splits the
	 * first tick its health is at or below each threshold.
	 */
	public void onBossHealth(double fraction)
	{
		if (state != State.BOSS)
		{
			return;
		}
		if (fraction <= 0.75)
		{
			split(Milestone.HUNLLEF_75);
		}
		if (fraction <= 0.50)
		{
			split(Milestone.HUNLLEF_50);
		}
		if (fraction <= 0.25)
		{
			split(Milestone.HUNLLEF_25);
		}
	}

	public void onLocalPlayerDeath()
	{
		if (isRunning())
		{
			diedThisRun = true;
		}
	}

	/**
	 * Stop tracking (plugin turned off). Returns the run that was in progress so it can still
	 * be saved: marked ABANDONED if mid-run, or as completed if the Hunllef was already dead.
	 */
	public Run abandon()
	{
		Run run = null;
		if (isRunning())
		{
			current.setEndReason(Run.EndReason.ABANDONED);
			run = end(false);
		}
		else if (state == State.FINISHED)
		{
			run = end(true);
		}
		state = State.IDLE;
		current = null;
		primed = false;
		return run;
	}

	private void start(long now)
	{
		current = new Run();
		current.setStartedAt(now);
		perfectedTypes.clear();
		bestWeaponTier = 0;
		armourSlots.clear();
		ticksSinceFinish = 0;
		diedThisRun = false;
		state = State.PREP;
	}

	private void finish()
	{
		split(Milestone.HUNLLEF);
		current.setCompleted(true);
		current.setEndReason(Run.EndReason.COMPLETED);
		ticksSinceFinish = 0;
		state = State.FINISHED;
	}

	private Run end(boolean completed)
	{
		Run run = current;
		run.setCompleted(completed);
		if (run.getEndReason() == null)
		{
			run.setEndReason(completed ? Run.EndReason.COMPLETED
				: diedThisRun ? Run.EndReason.DIED : Run.EndReason.LEFT);
		}
		lastRun = run;
		current = null;
		state = State.IDLE;
		return run;
	}

	private void split(Milestone milestone)
	{
		current.getSplits().putIfAbsent(milestone, current.getTicks());
	}

	private void applyMode(Run.Mode mode)
	{
		if (current != null && current.getMode() == Run.Mode.UNKNOWN && mode != Run.Mode.UNKNOWN)
		{
			current.setMode(mode);
		}
	}

	private static int weaponTier(String tier)
	{
		switch (tier)
		{
			case "perfected":
				return 3;
			case "attuned":
				return 2;
			default:
				return 1;
		}
	}

	private static Run.Mode modeFromName(String lowerName)
	{
		if (lowerName.startsWith("corrupted"))
		{
			return Run.Mode.CORRUPTED;
		}
		if (lowerName.startsWith("crystal"))
		{
			return Run.Mode.NORMAL;
		}
		return Run.Mode.UNKNOWN;
	}

}

package com.cgsplits;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import lombok.Value;

/**
 * Tracks the current play session: runs started, resets, Hunllef room enters, enters per hour
 * (EPH) and average enter time, overall and split by armour worn on entry.
 *
 * The session clock runs all session long, including the short trips through the lobby between
 * runs, so EPH reflects real play time. If the player stays outside the instance for more than
 * {@link #PAUSE_AFTER_TICKS_OUTSIDE} ticks (AFK, banking, logged out) the clock pauses until
 * they're back in a run. A session starts with its first run and lasts until reset manually or
 * the client restarts.
 *
 * Written from the client thread and read from the Swing/overlay threads, hence synchronized.
 */
public class SessionTracker
{
	/** Ticks outside the instance before the session clock pauses. */
	static final int PAUSE_AFTER_TICKS_OUTSIDE = 5;

	@Value
	public static class EnterStats
	{
		int count;
		int averageTicks;
	}

	@Value
	public static class Snapshot
	{
		boolean active;
		/** The clock is paused because the player has been out of the instance for a while. */
		boolean paused;
		/** Session time that counts towards EPH. */
		long elapsedMs;
		int runs;
		int resets;
		int enters;
		int averageEnterTicks;
		double entersPerHour;
		/** Only armour types with at least one enter are present. */
		Map<Armour, EnterStats> byArmour;

		/** Enters with this armour so far this session. */
		public int entersWith(Armour armour)
		{
			EnterStats stats = byArmour.get(armour);
			return stats == null ? 0 : stats.getCount();
		}
	}

	private boolean active;
	private long accumulatedMs;
	private boolean clockRunning;
	private long clockResumedAt;
	private int ticksOutside;
	private int runs;
	private int resets;
	private int enters;
	private long totalEnterTicks;
	private final Map<Armour, int[]> armourEnters = new EnumMap<>(Armour.class); // {count, totalTicks}

	public synchronized void onRunStarted(long now)
	{
		active = true;
		runs++;
		ticksOutside = 0;
		resumeClock(now);
	}

	/**
	 * Called every game tick. Inside the instance the clock runs; outside it keeps running for
	 * up to {@link #PAUSE_AFTER_TICKS_OUTSIDE} ticks (time between runs counts) and then pauses.
	 */
	public synchronized void onTick(boolean inInstance, long now)
	{
		if (!active)
		{
			return;
		}
		if (inInstance)
		{
			ticksOutside = 0;
			resumeClock(now);
		}
		else if (++ticksOutside > PAUSE_AFTER_TICKS_OUTSIDE)
		{
			pauseClock(now);
		}
	}

	/** Pause straight away, e.g. on logout or world hop. */
	public synchronized void pause(long now)
	{
		if (active)
		{
			ticksOutside = PAUSE_AFTER_TICKS_OUTSIDE + 1;
			pauseClock(now);
		}
	}

	/** The player walked into the Hunllef room, {@code enterTicks} ticks into the run. */
	public synchronized void onEnter(int enterTicks, Armour armour)
	{
		if (!active)
		{
			return;
		}
		enters++;
		totalEnterTicks += enterTicks;
		if (armour != null)
		{
			int[] stats = armourEnters.computeIfAbsent(armour, a -> new int[2]);
			stats[0]++;
			stats[1] += enterTicks;
		}
	}

	/** @param reset the run ended (died or left) before reaching the Hunllef room */
	public synchronized void onRunEnded(boolean reset)
	{
		if (active && reset)
		{
			resets++;
		}
	}

	public synchronized void reset()
	{
		active = false;
		accumulatedMs = 0;
		clockRunning = false;
		clockResumedAt = 0;
		ticksOutside = 0;
		runs = 0;
		resets = 0;
		enters = 0;
		totalEnterTicks = 0;
		armourEnters.clear();
	}

	public synchronized Snapshot snapshot(long now)
	{
		if (!active)
		{
			return new Snapshot(false, false, 0, 0, 0, 0, 0, 0, Collections.emptyMap());
		}
		long elapsed = accumulatedMs + (clockRunning ? Math.max(0, now - clockResumedAt) : 0);
		double hours = elapsed / 3_600_000.0;
		double eph = hours > 0 ? enters / hours : 0;

		Map<Armour, EnterStats> byArmour = new EnumMap<>(Armour.class);
		armourEnters.forEach((armour, s) -> byArmour.put(armour, new EnterStats(s[0], average(s[1], s[0]))));

		return new Snapshot(true, !clockRunning, elapsed, runs, resets, enters, average(totalEnterTicks, enters), eph,
			Collections.unmodifiableMap(byArmour));
	}

	private void resumeClock(long now)
	{
		if (!clockRunning)
		{
			clockRunning = true;
			clockResumedAt = now;
		}
	}

	private void pauseClock(long now)
	{
		if (clockRunning)
		{
			accumulatedMs += Math.max(0, now - clockResumedAt);
			clockRunning = false;
		}
	}

	private static int average(long total, int count)
	{
		return count == 0 ? 0 : (int) Math.round((double) total / count);
	}
}

package com.cgsplits;

final class TimeFormat
{
	static final int MS_PER_TICK = 600;

	private TimeFormat()
	{
	}

	/** 700 ticks -> "7:00.0"; minutes are dropped under a minute, so 10 ticks -> "6.0" */
	static String ticks(int ticks)
	{
		long ms = (long) ticks * MS_PER_TICK;
		long minutes = ms / 60_000;
		long seconds = (ms / 1000) % 60;
		long tenths = (ms / 100) % 10;
		if (minutes == 0)
		{
			return String.format("%d.%d", seconds, tenths);
		}
		return String.format("%d:%02d.%d", minutes, seconds, tenths);
	}

	private static final java.util.regex.Pattern OFFICIAL = java.util.regex.Pattern.compile("(\\d+):(\\d{2})(?:\\.(\\d+))?");

	/** The game's chat-message time, e.g. "2:18.60", in ticks (231), or null if unparseable. */
	static Integer parseOfficial(String time)
	{
		if (time == null)
		{
			return null;
		}
		java.util.regex.Matcher m = OFFICIAL.matcher(time);
		if (!m.find())
		{
			return null;
		}
		double seconds = Integer.parseInt(m.group(1)) * 60 + Integer.parseInt(m.group(2));
		if (m.group(3) != null)
		{
			seconds += Double.parseDouble("0." + m.group(3));
		}
		return (int) Math.round(seconds * 1000 / MS_PER_TICK);
	}

	/**
	 * A time typed by a person: "1:42", "1:42.6" or plain seconds like "58". Returns ticks,
	 * or null if it's blank or can't be read.
	 */
	static Integer parseUserTime(String time)
	{
		if (time == null || time.trim().isEmpty())
		{
			return null;
		}
		String t = time.trim();
		if (t.matches("\\d+(\\.\\d+)?"))
		{
			return (int) Math.round(Double.parseDouble(t) * 1000 / MS_PER_TICK);
		}
		return parseOfficial(t);
	}

	/** Whole seconds, rounded down: 10 ticks (6.0s) -> "6", 11 ticks (6.6s) -> "6", 104 ticks -> "1:02" */
	static String wholeSeconds(int ticks)
	{
		long totalSeconds = (long) ticks * MS_PER_TICK / 1000;
		if (totalSeconds < 60)
		{
			return String.valueOf(totalSeconds);
		}
		return String.format("%d:%02d", totalSeconds / 60, totalSeconds % 60);
	}

	/** Wall-clock duration, 3_725_000 ms -> "1:02:05" */
	static String duration(long ms)
	{
		long totalSeconds = ms / 1000;
		return String.format("%d:%02d:%02d", totalSeconds / 3600, (totalSeconds / 60) % 60, totalSeconds % 60);
	}

	/** On-screen EPH: drops the decimals without rounding, 4.99 -> "4". */
	static String eph(double entersPerHour)
	{
		return String.valueOf((long) Math.floor(entersPerHour));
	}

	/** Sidebar EPH: one decimal, cut off rather than rounded, 4.567 -> "4.5". */
	static String ephPrecise(double entersPerHour)
	{
		// Locale.ROOT so it's always "4.5", never "4,5"
		return String.format(java.util.Locale.ROOT, "%.1f", Math.floor(entersPerHour * 10) / 10);
	}

	/** -5 ticks -> "-3.0", 105 ticks -> "+1:03.0" */
	static String delta(int ticks)
	{
		String sign = ticks < 0 ? "-" : "+";
		long ms = (long) Math.abs(ticks) * MS_PER_TICK;
		long minutes = ms / 60_000;
		long seconds = (ms / 1000) % 60;
		long tenths = (ms / 100) % 10;
		if (minutes > 0)
		{
			return String.format("%s%d:%02d.%d", sign, minutes, seconds, tenths);
		}
		return String.format("%s%d.%d", sign, seconds, tenths);
	}
}

package com.cgsplits;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** How the on-screen timer displays time. */
@Getter
@RequiredArgsConstructor
public enum TimerPrecision
{
	/** Every game tick: 6.0, 6.6, 7.2 ... */
	TICKS("Ticks (0.6s)"),
	/** Whole seconds only: 6, 7, 8 ... */
	SECONDS("Seconds");

	private final String name;

	String format(int ticks)
	{
		return this == SECONDS ? TimeFormat.wholeSeconds(ticks) : TimeFormat.ticks(ticks);
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.cgsplits;

/**
 * The current Corrupted Gauntlet world record. Shown at the top of the sidebar and used by the
 * "World Record" pace comparison.
 *
 * UPDATE HERE when a new world record is set: change the holder and the four times, rebuild,
 * and everything else follows. Times are "m:ss" (or "m:ss.s").
 */
public final class WorldRecord
{
	public static final String HOLDER = "rawr simon";

	/** Preparation: run start to entering the Hunllef room. */
	public static final String PREP = "1:42";
	/** Hunllef at 50% HP, from the start of the run. */
	public static final String HALF_HP = "2:53";
	/** The Hunllef fight on its own, Enter to kill. */
	public static final String FIGHT = "2:15";
	/** Overall time. */
	public static final String TOTAL = "3:57";

	/**
	 * The Top 3 shown at the top of the sidebar, fastest first:
	 * { name, overall time, armour tag, preparation, Hunllef fight }.
	 * UPDATE HERE when the leaderboard changes. A blank name shows as "-"; the tag and the two
	 * split times are optional (hover a place to see its splits).
	 */
	public static final String[][] TOP_3 = {
		{"rawr simon", "3:57.0", "T1 Prep", "1:42", "2:15"},
		{"Slinkey", "3:58.8", "No Arm", "1:30.6", "2:28.2"},
		// No full VOD, so the prep type isn't known
		{"Tate", "3:59.4", "", "1:27.6", "2:31.8"},
	};

	private WorldRecord()
	{
	}

	/** World record time for a timer split, in ticks, or null if there isn't one. */
	static Integer ticks(Milestone milestone)
	{
		switch (milestone)
		{
			case BOSS_ROOM:
				return TimeFormat.parseUserTime(PREP);
			case HUNLLEF_50:
				return TimeFormat.parseUserTime(HALF_HP);
			case HUNLLEF_FIGHT:
				return TimeFormat.parseUserTime(FIGHT);
			case HUNLLEF:
				return TimeFormat.parseUserTime(TOTAL);
			default:
				return null;
		}
	}
}

